import { STATUS_COLOR, PRIORITY_COLOR } from '../../lib/constants';

export function StatusBadge({ status }) {
  const color = STATUS_COLOR[status] || 'var(--text-3)';
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', gap: 5,
      padding: '3px 10px', borderRadius: 20,
      background: `color-mix(in srgb, ${color} 12%, transparent)`,
      border: `1px solid color-mix(in srgb, ${color} 30%, transparent)`,
      color, fontSize: 11, fontWeight: 700,
    }}>
      <span style={{ width: 5, height: 5, borderRadius: '50%', background: color }} />
      {status}
    </span>
  );
}

export function PriorityBadge({ priority }) {
  const color = PRIORITY_COLOR[priority] || 'var(--text-3)';
  return (
    <span style={{
      padding: '2px 8px', borderRadius: 20,
      background: `color-mix(in srgb, ${color} 12%, transparent)`,
      border: `1px solid color-mix(in srgb, ${color} 30%, transparent)`,
      color, fontSize: 10, fontWeight: 700,
    }}>
      {priority}
    </span>
  );
}

export function RoleBadge({ role }) {
  const colors = { Admin: 'var(--accent)', Operator: 'var(--blue)', Viewer: 'var(--purple)' };
  const c = colors[role] || 'var(--text-3)';
  return (
    <span style={{
      padding: '2px 10px', borderRadius: 20,
      background: `color-mix(in srgb, ${c} 12%, transparent)`,
      border: `1px solid color-mix(in srgb, ${c} 30%, transparent)`,
      color: c, fontSize: 11, fontWeight: 700,
    }}>
      {role}
    </span>
  );
}
