import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../supabaseClient';
import { exportCSV } from '../../lib/helpers';

const PAGE = 50;
const ACTION_COLOR = {
  insert: 'var(--accent)', update: 'var(--blue)', delete: 'var(--red)',
  login: 'var(--purple)', logout: 'var(--text-dim)', export: 'var(--orange)', print: 'var(--orange)',
};
const ACTION_LABEL = { insert: 'Created', update: 'Updated', delete: 'Deleted', login: 'Login', logout: 'Logout', export: 'Export', print: 'Print' };
const ENTITY_LABEL = {
  assets: 'Asset', facilities: 'Facility', antennas: 'Antenna', profiles: 'User', organizations: 'Organization',
  checkouts: 'Checkout', requests: 'Request', deliveries: 'Delivery', movements: 'Movement', sub_assets: 'Sub-asset',
  maintenance_history: 'Maintenance', asset_attachments: 'Attachment', invite_codes: 'Invite code',
  subscriptions: 'Subscription', packages: 'Package', system_settings: 'Settings',
};
const RANGES = [ ['1', 'Last 24 h'], ['7', 'Last 7 days'], ['30', 'Last 30 days'], ['90', 'Last 90 days'], ['all', 'All time'] ];

const fmtVal = v => v === null || v === undefined || v === '' ? '—' : typeof v === 'object' ? JSON.stringify(v) : String(v);

export default function ActivityLogPage() {
  const [rows, setRows]       = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState('');
  const [more, setMore]       = useState(false);
  const [orgs, setOrgs]       = useState([]);
  const [open, setOpen]       = useState(null);
  const [f, setF] = useState({ org: '', action: '', entity: '', range: '7', q: '' });

  useEffect(() => {
    supabase.from('organizations').select('id,name').order('name').then(({ data }) => setOrgs(data || []));
  }, []);

  const load = useCallback(async (offset = 0) => {
    setLoading(true); setError('');
    let q = supabase.from('activity_log').select('*').order('created_at', { ascending: false }).range(offset, offset + PAGE - 1);
    if (f.org)    q = q.eq('org_id', f.org);
    if (f.action) q = q.eq('action', f.action);
    if (f.entity) q = q.eq('entity', f.entity);
    if (f.range !== 'all') q = q.gte('created_at', new Date(Date.now() - Number(f.range) * 86400000).toISOString());
    const s = f.q.trim().replace(/[%,()]/g, '');
    if (s) q = q.or(`user_email.ilike.%${s}%,user_name.ilike.%${s}%,entity_name.ilike.%${s}%`);
    const { data, error } = await q;
    setLoading(false);
    if (error) {
      setError(/activity_log/.test(error.message) ? 'Activity log table not found — run supabase/migration_activity_log.sql first.' : error.message);
      return;
    }
    setRows(prev => offset ? [...prev, ...data] : data);
    setMore(data.length === PAGE);
  }, [f]);

  useEffect(() => { const t = setTimeout(() => load(0), 250); return () => clearTimeout(t); }, [load]);

  const today = rows.filter(r => new Date(r.created_at).toDateString() === new Date().toDateString());
  const users = new Set(rows.map(r => r.user_id)).size;

  const doExport = () => exportCSV(rows.map(r => ({
    Time: new Date(r.created_at).toLocaleString('en-MY'), User: r.user_name || '', Email: r.user_email || '',
    Role: r.user_role || '', Organization: r.org_name || '', Action: ACTION_LABEL[r.action] || r.action,
    Module: ENTITY_LABEL[r.entity] || r.entity || '', Item: r.entity_name || '',
    Changes: r.details ? JSON.stringify(r.details) : '',
  })), `activity-log-${new Date().toISOString().slice(0, 10)}.csv`, ['Time','User','Email','Role','Organization','Action','Module','Item','Changes'].map(k => ({ key: k, label: k })));

  const set = k => e => setF(p => ({ ...p, [k]: e.target.value }));

  return (
    <div className="card" style={{ padding: 24 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12, flexWrap: 'wrap', marginBottom: 16 }}>
        <div>
          <div style={{ fontFamily: "'Syne',sans-serif", fontWeight: 800, fontSize: 18, color: 'var(--text)' }}>User Activity Log</div>
          <div style={{ fontSize: 12, color: 'var(--text-dim)', marginTop: 3 }}>
            Logins and every create / update / delete by users across all organizations. RFID bridge reads are not included.
          </div>
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          <button className="btn" style={{ fontSize: 12, padding: '8px 14px', background: 'var(--bg-input)', color: 'var(--text-2)', border: '1px solid var(--border)' }} onClick={() => load(0)}>↻ Refresh</button>
          <button className="btn" style={{ fontSize: 12, padding: '8px 14px', background: 'var(--accent)', color: '#060b10' }} onClick={doExport} disabled={!rows.length}>Export CSV</button>
        </div>
      </div>

      <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginBottom: 14 }}>
        {[['Entries shown', rows.length], ['Today', today.length], ['Users', users], ['Logins', rows.filter(r => r.action === 'login').length]].map(([l, v]) => (
          <div key={l} style={{ flex: '1 1 120px', background: 'var(--bg-input)', border: '1px solid var(--border)', borderRadius: 8, padding: '10px 14px' }}>
            <div style={{ fontSize: 11, color: 'var(--text-dim)' }}>{l}</div>
            <div style={{ fontSize: 20, fontWeight: 700, color: 'var(--text)', marginTop: 2 }}>{v}</div>
          </div>
        ))}
      </div>

      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 14 }}>
        <input className="inp" placeholder="Search user, email or item…" value={f.q} onChange={set('q')} style={{ flex: '2 1 200px' }} />
        <select className="sel" value={f.org} onChange={set('org')} style={{ flex: '1 1 150px' }}>
          <option value="">All organizations</option>
          {orgs.map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
        </select>
        <select className="sel" value={f.action} onChange={set('action')} style={{ flex: '1 1 120px' }}>
          <option value="">All actions</option>
          {Object.entries(ACTION_LABEL).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
        </select>
        <select className="sel" value={f.entity} onChange={set('entity')} style={{ flex: '1 1 130px' }}>
          <option value="">All modules</option>
          {Object.entries(ENTITY_LABEL).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
        </select>
        <select className="sel" value={f.range} onChange={set('range')} style={{ flex: '1 1 120px' }}>
          {RANGES.map(([k, v]) => <option key={k} value={k}>{v}</option>)}
        </select>
      </div>

      {error && <div style={{ padding: 12, borderRadius: 8, background: 'rgba(224,87,87,.1)', color: 'var(--red)', fontSize: 13, marginBottom: 12 }}>{error}</div>}

      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: 760 }}>
          <thead>
            <tr style={{ borderBottom: '1px solid var(--border)' }}>
              {['Time', 'User', 'Organization', 'Action', 'Module', 'Item', ''].map(h => (
                <th key={h} style={{ textAlign: 'left', fontSize: 11, color: 'var(--text-dim)', fontWeight: 600, padding: '8px 10px', textTransform: 'uppercase', letterSpacing: '.04em' }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map(r => {
              const changes = r.action === 'update' && r.details ? Object.keys(r.details) : [];
              return [
                <tr key={r.id} className="row" style={{ borderBottom: '1px solid var(--border)', cursor: changes.length ? 'pointer' : 'default' }}
                    onClick={() => changes.length && setOpen(open === r.id ? null : r.id)}>
                  <td className="td" style={{ whiteSpace: 'nowrap', fontSize: 12, color: 'var(--text-muted)' }}>{new Date(r.created_at).toLocaleString('en-MY')}</td>
                  <td className="td">
                    <div style={{ fontSize: 13, color: 'var(--text)' }}>{r.user_name || r.user_email || '—'}</div>
                    <div style={{ fontSize: 11, color: 'var(--text-dim)' }}>{r.user_email}{r.user_role ? ` · ${r.user_role}` : ''}</div>
                  </td>
                  <td className="td" style={{ fontSize: 12, color: 'var(--text-2)' }}>{r.org_name || '—'}</td>
                  <td className="td">
                    <span style={{ fontSize: 11, fontWeight: 700, color: ACTION_COLOR[r.action] || 'var(--text-2)', border: `1px solid ${ACTION_COLOR[r.action] || 'var(--border)'}`, borderRadius: 4, padding: '2px 8px' }}>
                      {ACTION_LABEL[r.action] || r.action}
                    </span>
                  </td>
                  <td className="td" style={{ fontSize: 12, color: 'var(--text-2)' }}>{ENTITY_LABEL[r.entity] || r.entity || '—'}</td>
                  <td className="td" style={{ fontSize: 12, color: 'var(--text)', maxWidth: 240, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {r.entity_name || '—'}
                    {changes.length > 0 && <span style={{ color: 'var(--text-dim)' }}> · {changes.slice(0, 3).join(', ')}{changes.length > 3 ? '…' : ''}</span>}
                  </td>
                  <td className="td" style={{ fontSize: 11, color: 'var(--text-dim)' }}>{changes.length ? (open === r.id ? '▲' : '▼') : ''}</td>
                </tr>,
                open === r.id && (
                  <tr key={r.id + '-d'}>
                    <td colSpan={7} style={{ background: 'var(--bg-input)', padding: '10px 16px' }}>
                      <table style={{ borderCollapse: 'collapse', fontSize: 12 }}>
                        <tbody>
                          {changes.map(k => (
                            <tr key={k}>
                              <td style={{ padding: '3px 14px 3px 0', color: 'var(--text-dim)', fontFamily: 'var(--mono)' }}>{k}</td>
                              <td style={{ padding: '3px 10px', color: 'var(--red)', maxWidth: 300, wordBreak: 'break-all' }}>{fmtVal(r.details[k]?.from)}</td>
                              <td style={{ padding: '3px 6px', color: 'var(--text-dim)' }}>→</td>
                              <td style={{ padding: '3px 10px', color: 'var(--accent)', maxWidth: 300, wordBreak: 'break-all' }}>{fmtVal(r.details[k]?.to)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </td>
                  </tr>
                ),
              ];
            })}
          </tbody>
        </table>
      </div>

      {!loading && !error && rows.length === 0 && (
        <div style={{ textAlign: 'center', padding: '28px 0', color: 'var(--text-dim)', fontSize: 13 }}>No activity for these filters.</div>
      )}
      {loading && <div style={{ textAlign: 'center', padding: 16, color: 'var(--text-dim)', fontSize: 13 }}>Loading…</div>}
      {more && !loading && (
        <div style={{ textAlign: 'center', marginTop: 14 }}>
          <button className="btn" style={{ fontSize: 12, padding: '8px 18px', background: 'var(--bg-input)', color: 'var(--text-2)', border: '1px solid var(--border)' }} onClick={() => load(rows.length)}>Show more</button>
        </div>
      )}
    </div>
  );
}
