import { createContext, useContext, useEffect, useRef, useState } from 'react';
import { supabase } from '../supabaseClient';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user,    setUser]    = useState(null);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);
  const lastUid = useRef(null);

  const fetchProfile = async (userId) => {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .eq('id', userId)
      .single();
    if (!error && data) setProfile(data);
  };

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
      if (session?.user && lastUid.current !== session.user.id) { lastUid.current = session.user.id; fetchProfile(session.user.id); }
      setLoading(false);
    });

    // Token refreshes fire when the browser tab regains focus. Reloading the profile then
    // re-ran every loader and showed the full-screen spinner, unmounting open forms.
    // Only react when the signed-in user actually changes.
    const { data: listener } = supabase.auth.onAuthStateChange((event, session) => {
      const next = session?.user ?? null;
      // keep the same object on plain token refresh; USER_UPDATED (e.g. password set) must pass through
      setUser(prev => (event !== 'USER_UPDATED' && prev && prev.id === next?.id) ? prev : next);
      if (!next) { lastUid.current = null; setProfile(null); return; }
      if (lastUid.current === next.id) return;
      lastUid.current = next.id;
      // defer: running a query inside this callback can deadlock the auth client
      setTimeout(() => fetchProfile(next.id), 0);
    });

    return () => listener.subscription.unsubscribe();
  }, []);

  const signIn = async (email, password) => {
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    if (!error) supabase.rpc('log_activity', { p_action: 'login' }).then(() => {}, () => {});
    return { data, error };
  };

  // Used by RegisterPage — meta carries name, role, org_id
  const signUp = async (email, password, meta = {}) => {
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: { data: meta },
    });
    return { data, error };
  };

  const signOut = async () => {
    try { await supabase.rpc('log_activity', { p_action: 'logout' }); } catch {}
    await supabase.auth.signOut();
    setUser(null);
    setProfile(null);
  };

  const value = { user, profile, loading, signIn, signUp, signOut };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used inside <AuthProvider>');
  return ctx;
};
