// filled: tint the whole card with the accent colour (used for maintenance alerts).
export default function StatCard({ icon, label, value, sub, accent = 'var(--accent)', onClick, filled = false }) {
  // filled = soft tint of the accent (not solid), text stays readable in light + dark
  const tint = (p) => 'color-mix(in srgb, ' + accent + ' ' + p + '%, var(--bg-card))';
  const fg = null;
  return (
    <div
      onClick={onClick}
      style={{
        background: filled ? tint(16) : 'var(--bg-card)',
        border: '1px solid ' + (filled ? tint(55) : 'var(--border)'), borderRadius: 12,
        padding: '20px 22px', cursor: onClick ? 'pointer' : 'default',
        transition: 'border-color 0.15s, filter 0.15s',
        display: 'flex', flexDirection: 'column', gap: 8,
      }}
      onMouseEnter={e => onClick && (filled ? (e.currentTarget.style.filter = 'brightness(1.08)') : (e.currentTarget.style.borderColor = accent))}
      onMouseLeave={e => onClick && (filled ? (e.currentTarget.style.filter = '') : (e.currentTarget.style.borderColor = 'var(--border)'))}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
        <div style={{
          width: 36, height: 36, borderRadius: 9,
          background: filled ? tint(30) : 'color-mix(in srgb, ' + accent + ' 12%, transparent)',
          border: '1px solid ' + (filled ? tint(60) : 'color-mix(in srgb, ' + accent + ' 25%, transparent)'),
          display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18,
          color: fg || accent,
        }}>
          {icon}
        </div>
        <div style={{ fontSize: 11, color: filled ? accent : 'var(--text-4)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.6px', opacity: filled ? 0.92 : 1 }}>
          {label}
        </div>
      </div>
      <div style={{ fontSize: 28, fontWeight: 800, color: fg || 'var(--text)', fontFamily: "'Syne',sans-serif", lineHeight: 1 }}>
        {value}
      </div>
      {sub && <div style={{ fontSize: 11, color: fg || 'var(--text-3)', opacity: filled ? 0.9 : 1 }}>{sub}</div>}
    </div>
  );
}
