import { useEffect } from 'react';
import { useApp } from '../../contexts/AppContext';
import { useTenant } from '../../contexts/TenantContext';
import { useTheme } from '../../contexts/ThemeContext';
import { Sun, Moon } from 'lucide-react';

const PAGE_LABELS = {
  dashboard:  { label: 'Dashboard'        },
  assets:     { label: 'Assets'            },
  facilities: { label: 'Facilities'        },
  checkout:   { label: 'Asset Checkout'    },
  requests:   { label: 'Transfer Requests' },
  deliveries: { label: 'Deliveries'        },
  tracking:   { label: 'Live Tracking'     },
  reports:    { label: 'Reports'            },
  users:      { label: 'User Management'   },
  settings:   { label: 'System Settings'  },
};

export default function Header({ page, onMenuClick }) {
  const { reload } = useApp();
  const { org }    = useTenant();
  const { theme, toggleTheme } = useTheme();

  // Use org name as system name; cache so LoginPage can read it before auth
  const companyName = org?.name || '';
  const systemName  = org?.system_name || companyName;
  if (companyName) localStorage.setItem('rfid_wms_company', companyName);
  if (systemName)  localStorage.setItem('rfid_wms_system_name', systemName);

  const { label } = PAGE_LABELS[page] || { label: page };
  const now = new Date().toLocaleString('en-MY', {
    weekday: 'short', day: 'numeric', month: 'short',
    hour: '2-digit', minute: '2-digit',
  });

  // Update browser tab title
  useEffect(() => {
    document.title = companyName
      ? `${label} — ${companyName}`
      : label;
  }, [page, companyName, label]);

  return (
    <header style={{
      height: 58, flexShrink: 0,
      borderBottom: '1px solid var(--border)',
      display: 'flex', alignItems: 'center',
      padding: '0 16px', gap: 12, background: 'var(--bg-side)',
    }}>
      {/* Hamburger — hidden on desktop via CSS */}
      <button
        className="hamburger-btn"
        onClick={onMenuClick}
        style={{
          background: 'none', border: '1px solid var(--border)', borderRadius: 7,
          color: 'var(--text-3)', fontSize: 18, cursor: 'pointer',
          padding: '5px 10px', lineHeight: 1, flexShrink: 0,
        }}
      >☰</button>

      <div style={{ fontFamily: "'Syne',sans-serif", fontWeight: 800, fontSize: 15, color: 'var(--text)', whiteSpace: 'nowrap' }}>
        {label}
      </div>

      {/* Company name pill */}
      {companyName && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }} className="header-orgname">
          <div style={{ width: 1, height: 18, background: 'var(--border)' }} />
          <div style={{
            fontSize: 12, fontFamily: "'Syne',sans-serif", fontWeight: 700,
            color: 'var(--accent)', background: 'rgba(0,180,127,.08)',
            border: '1px solid rgba(0,180,127,.2)', borderRadius: 6,
            padding: '3px 10px', whiteSpace: 'nowrap',
          }}>
            {companyName}
          </div>
        </div>
      )}

      <div style={{ flex: 1 }} />

      <div className="header-clock" style={{ fontSize: 11, color: 'var(--text-4)', fontFamily: "'IBM Plex Mono',monospace", whiteSpace: 'nowrap' }}>
        {now}
      </div>
      <button
        onClick={toggleTheme}
        title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
        style={{
          background: 'none', border: '1px solid var(--border)', borderRadius: 7,
          color: 'var(--text-3)', cursor: 'pointer',
          padding: '5px 10px', display: 'inline-flex', alignItems: 'center', flexShrink: 0,
        }}
        onMouseEnter={e => e.currentTarget.style.borderColor = 'var(--accent)'}
        onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}
      >{theme === 'dark' ? <Sun size={14}/> : <Moon size={14}/>}</button>
      <button
        onClick={reload}
        title="Refresh all data"
        style={{
          background: 'none', border: '1px solid var(--border)', borderRadius: 7,
          color: 'var(--text-3)', fontSize: 14, cursor: 'pointer',
          padding: '5px 10px', transition: 'all 0.15s', flexShrink: 0,
        }}
        onMouseEnter={e => e.currentTarget.style.borderColor = 'var(--accent)'}
        onMouseLeave={e => e.currentTarget.style.borderColor = 'var(--border)'}
      >↻</button>
    </header>
  );
}
